.canvas-head h2 .ax-c { color: var(--c-c); }
.canvas-head h2 .ax-s { color: var(--c-s); }
.canvas-tools { margin-left: auto; display: flex; gap: 10px; align-items: center; }
.tool { color: var(--dim); font-size: 11px; display: inline-flex; gap: 4px; align-items: center; cursor: pointer; }
.tool input { accent-color: var(--accent); }

.plot-area { position: relative; flex: 1; min-height: 0; }
#plot { position: absolute; inset: 0; width: 100%; height: 100%; display: block; cursor: crosshair; }

.empty-note {
  position: absolute; inset: 0; margin: auto;
  width: fit-content; height: fit-content;
  background: var(--panel2); border: 1px solid var(--border2);
  border-radius: 10px; padding: 18px 26px; text-align: center;
  box-shadow: 0 8px 30px rgba(0,0,0,.5);
}
.empty-note .hint { margin: 4px 0 12px; }

.legend {
  display: flex; flex-wrap: wrap; gap: 5px 14px; align-items: center;
  padding: 7px 12px; border-top: 1px solid var(--border);
  font-size: 11px; color: var(--dim); min-height: 34px;
}
.lg-item { display: inline-flex; align-items: center; gap: 5px; }
.lg-sw { width: 9px; height: 9px; border-radius: 2.5px; }
.lg-n { font: 10px var(--mono); color: var(--faint); }
.lg-bar { width: 110px; height: 8px; border-radius: 4px; border: 1px solid var(--border2); }
.lg-sep { width: 1px; height: 14px; background: var(--border); margin: 0 4px; }
.lg-dot { border-radius: 50%; background: var(--faint); display: inline-block; }

/* ---------- inspector ---------- */
.inspector { display: flex; flex-direction: column; gap: 8px; min-height: 0; }
.sec { padding: 9px 12px 10px; display: flex; flex-direction: column; }
.sec-filters { max-height: 47%; }
.sec-selection { flex: none; }
.sec-ledger { flex: 1; min-height: 148px; }
.sec-head { display: flex; align-items: center; gap: 8px; margin-bottom: 6px; }
.sec-head .hint { margin-left: auto; font-size: 10px; }
.sec-head > div { margin-left: auto; display: flex; gap: 5px; }

/* filters */
.chips { display: flex; flex-wrap: wrap; gap: 4px; margin-bottom: 6px; }
.chips:empty { display: none; }
.chip {
  display: inline-flex; align-items: center; gap: 4px;
  background: var(--panel3); border: 1px solid var(--border2);
  border-radius: 999px; padding: 1.5px 4px 1.5px 9px; font-size: 10.5px;
}
.chip button { color: var(--dim); width: 14px; height: 14px; border-radius: 50%; font-size: 11px; line-height: 1; }
.chip button:hover { color: var(--danger); background: #2a2028; }

.filter-list { overflow-y: auto; margin: 0 -4px; padding: 0 4px; }
.f-row { padding: 6px 8px 7px; border: 1px solid transparent; border-radius: 6px; }
.f-row.active { border-color: #2c3d5e; background: rgba(76,194,255,.05); }
.f-head { display: flex; align-items: center; gap: 6px; font-size: 11.5px; }
.f-head .unit { color: var(--faint); font: 10px var(--mono); }
.f-clear { margin-left: auto; color: var(--faint); font-size: 12px; visibility: hidden; }
.f-row.active .f-clear { visibility: visible; }
.f-clear:hover { color: var(--danger); }

.dual-range { position: relative; height: 22px; margin-top: 2px; }
.dual-range input[type=range] {
  position: absolute; left: 0; right: 0; width: 100%; top: 3px;
  -webkit-appearance: none; appearance: none;
  background: transparent; pointer-events: none; height: 16px;
}
.dual-range input[type=range]::-webkit-slider-thumb {
  -webkit-appearance: none; appearance: none; pointer-events: auto;
  width: 11px; height: 11px; border-radius: 50%;
  background: var(--accent); border: 2px solid #0b2536;
  cursor: ew-resize; margin-top: 0;
}
.dual-range input[type=range]::-moz-range-thumb {
  pointer-events: auto; width: 10px; height: 10px; border-radius: 50%;
  background: var(--accent); border: 2px solid #0b2536; cursor: ew-resize;
}
.dual-range .track {
  position: absolute; top: 9px; left: 0; right: 0; height: 3px;
  background: var(--border2); border-radius: 2px; pointer-events: none;
}
.dual-range .fill { position: absolute; top: 9px; height: 3px; background: var(--accent); border-radius: 2px; pointer-events: none; opacity: .7; }
.f-vals { display: flex; justify-content: space-between; font: 10px var(--mono); color: var(--dim); margin-top: 1px; }

.f-checks { display: grid; grid-template-columns: 1fr 1fr; gap: 1px 8px; margin-top: 3px; }
.f-checks label { display: flex; gap: 5px; align-items: center; font-size: 11px; color: var(--dim); cursor: pointer; padding: 1.5px 0; }
.f-checks input { accent-color: var(--c-c); }
.f-checks .lg-sw { flex: none; }

.f-tree details { margin-top: 3px; }
.f-tree summary {
  cursor: pointer; font-size: 11px; color: var(--text);
  display: flex; align-items: center; gap: 6px; padding: 2px 0; list-style: none;
}
.f-tree summary::-webkit-details-marker { display: none; }
.f-tree summary::before { content: "▸"; color: var(--faint); font-size: 9px; }
.f-tree details[open] summary::before { content: "▾"; }
.f-tree .tree-kids { margin: 0 0 3px 14px; display: flex; flex-direction: column; }

/* selection */
.sel-list { list-style: none; max-height: 108px; overflow-y: auto; margin-bottom: 4px; }
.sel-list:empty { display: none; }
.sel-list li { display: flex; align-items: center; gap: 6px; padding: 2px 0; font: 11.5px var(--mono); }
.sel-list .sel-dot { width: 7px; height: 7px; border-radius: 50%; background: var(--sel); flex: none; }
.sel-list .sel-x { margin-left: auto; color: var(--faint); }
.sel-list .sel-x:hover { color: var(--danger); }

/* ledger */
.ledger-list { list-style: none; overflow-y: auto; flex: 1; min-height: 0; }
.ledger-list li { border-bottom: 1px solid #161c2a; }
.l-entry {
  width: 100%; text-align: left;
  display: grid; grid-template-columns: 30px 42px 1fr auto; gap: 2px 7px;
  padding: 5px 8px 5px 6px; align-items: baseline;
  border-left: 2px solid transparent;
}
.l-entry:hover:not(.cur) { background: var(--panel2); }
.l-entry.cur { border-left-color: var(--accent); background: rgba(76,194,255,.07); cursor: default; }
.l-seq { font: 10px var(--mono); color: var(--faint); }
.l-kind {
  font-size: 9.5px; padding: 0 5px; border-radius: 999px; text-align: center;
  border: 1px solid var(--border2); color: var(--dim); white-space: nowrap; justify-self: start;
}
.k-projection { color: var(--c-y); border-color: #3d3353; }
.k-filter { color: var(--c-c); border-color: #2c4a33; }
.k-selection { color: var(--sel); border-color: #4a3f22; }
.k-viewport { color: #9ecbff; border-color: #2c3d5e; }
.k-revert, .k-reset { color: var(--danger); border-color: #4a2a2a; }
.l-label { font-size: 11.5px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.l-meta { display: flex; gap: 8px; grid-column: 3 / 5; font: 10px var(--mono); color: var(--faint); }
.l-meta .l-actor { color: var(--dim); }
.l-revert-hint { font: 9.5px var(--mono); color: var(--faint); justify-self: end; }
.l-entry:hover:not(.cur) .l-revert-hint { color: var(--accent); }
.l-entry.cur .l-revert-hint { visibility: hidden; }

/* tooltip */
.tooltip {
  position: fixed; z-index: 30; pointer-events: none;
  background: rgba(13, 17, 23, .96);
  border: 1px solid var(--border2); border-radius: 7px;
  padding: 8px 10px; font-size: 11px; max-width: 280px;
  box-shadow: 0 6px 24px rgba(0,0,0,.55);
}
.tt-name { font: 600 12px var(--mono); margin-bottom: 1px; }
.tt-sub { color: var(--dim); font-size: 10.5px; margin-bottom: 5px; }
.tt-row { display: flex; gap: 6px; align-items: center; padding: .5px 0; }
.tt-k { width: 14px; height: 14px; border-radius: 3.5px; display: inline-grid; place-items: center; font: 700 8.5px var(--mono); color: var(--bg); flex: none; }
.tt-v { font-family: var(--mono); }
.tt-extra { margin-top: 4px; color: var(--faint); font-size: 10.5px; border-top: 1px solid var(--border); padding-top: 4px; }

/* footer */
.foot {
  display: flex; gap: 8px; align-items: center;
  padding: 5px 14px; font-size: 10.5px; color: var(--faint);
  background: var(--panel); border-top: 1px solid var(--border);
  white-space: nowrap; overflow: hidden;
}
.foot .sep { color: var(--border2); }

/* fatal error state */
.fatal { position: fixed; inset: 0; background: var(--bg); display: grid; place-items: center; z-index: 99; }
.fatal-box { text-align: center; color: var(--danger); }
.fatal-box p { color: var(--dim); margin-top: 6px; font-family: var(--mono); }

/* scrollbars */
::-webkit-scrollbar { width: 9px; height: 9px; }
::-webkit-scrollbar-thumb { background: #262f42; border-radius: 5px; border: 2px solid var(--panel); }
::-webkit-scrollbar-track { background: transparent; }

