      filters: {},   /* dimId -> {lo,hi} | {off:[values]} ; range in data units */
      selection: [], /* record ids, ordered */
      viewports: {}, /* projKey -> {k,tx,ty} : per-projection viewport memory */
      k: 1, tx: 0, ty: 0
