      return CAT_COLORS[(i < 0 ? 0 : i) % CAT_COLORS.length];
    }
    if (cd.type === 'tree') return SECTOR_COLORS[rec.sectorId] || '#8b94a7';
    var t = (tOf(cd, rec[cd.id]) - tOf(cd, cd.dom[0])) / (tOf(cd, cd.dom[1]) - tOf(cd, cd.dom[0]));
