  }
  function snapshot(s) {
    return JSON.parse(JSON.stringify({
      channels: s.channels, logAxes: s.logAxes, filters: s.filters,
      selection: s.selection, viewports: s.viewports, k: s.k, tx: s.tx, ty: s.ty
