4	(function () {
5	  'use strict';
6	
7	  function mulberry32(a) {
8	    return function () {
9	      a |= 0; a = (a + 0x6D2B79F5) | 0;
10	      var t = Math.imul(a ^ (a >>> 15), 1 | a);
11	      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
12	      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
13	    };
14	  }
15	  var rand = mulberry32(0xC0FFEE);
16	  function gauss() {
17	    var u = 0, v = 0;
18	    while (u === 0) u = rand();
19	    while (v === 0) v = rand();
20	    return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * v);
21	  }
22	  function pick(pairs) {
23	    var s = 0, i;
24	    for (i = 0; i < pairs.length; i++) s += pairs[i][1];
25	    var r = rand() * s;
26	    for (i = 0; i < pairs.length; i++) { r -= pairs[i][1]; if (r <= 0) return pairs[i][0]; }
27	    return pairs[pairs.length - 1][0];
28	  }
29	  function clamp(v, a, b) { return v < a ? a : v > b ? b : v; }
30	
31	  /* hierarchy: sector (天区) → constellation (星座) → system (恒星系统) → planet (行星) */
32	  var SECTORS = [
33	    { id: 'north',   name: 'North Cap',       consts: [['Orion', 'Ori'], ['Cygnus', 'Cyg'], ['Lyra', 'Lyr']] },
34	    { id: 'equator', name: 'Equatorial Belt', consts: [['Hydra', 'Hya'], ['Cetus', 'Cet'], ['Bootes', 'Boo']] },
