59	          var radiusE = clamp(1.12 * Math.pow(massE, 0.27) * Math.exp(gauss() * 0.25), 0.3, 16.5);
60	          var periodD = clamp(Math.exp(4.2 + gauss() * 1.8), 0.5, 22000);
61	          var tempK = clamp(1500 * Math.pow(periodD, -0.32) * Math.exp(gauss() * 0.4), 25, 2700);
62	          var year = 2009 + Math.floor(rand() * 17);
63	          var method = pick(METHODS);
