.tt-name { font: 600 12px var(--mono); margin-bottom: 1px; }
.tt-sub { color: var(--dim); font-size: 10.5px; margin-bottom: 5px; }
.tt-row { display: flex; gap: 6px; align-items: center; padding: .5px 0; }
