  --bg: #0b0e14;
  --panel: #11151f;
  --panel2: #161b28;
  --panel3: #1b2233;
  --border: #232a3a;
  --border2: #2d3648;
  --text: #d7dde8;
  --dim: #97a1b3;
  --faint: #7e8899;
  --accent: #4cc2ff;   /* channel X */
  --c-y: #d2a8ff;      /* channel Y */
  --c-c: #7ee787;      /* channel C */
  --c-s: #ffb454;      /* channel S */
  --sel: #ffd166;
  --danger: #ff7b72;
  --mono: ui-monospace, "Cascadia Mono", Consolas, "Courier New", monospace;
  --sans: system-ui, "Segoe UI", "Microsoft YaHei", sans-serif;
  color-scheme: dark;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html, body { height: 100%; }
body {
  background: var(--bg);
  color: var(--text);
  font: 12.5px/1.45 var(--sans);
  display: grid;
  grid-template-rows: auto 1fr auto;
  height: 100vh;
  overflow: hidden;
}

h2 { font-size: 12px; font-weight: 600; letter-spacing: .02em; color: var(--text); }
.hint { color: var(--dim); font-size: 11px; }
.count { color: var(--dim); font: 11px var(--mono); }
b { font-family: var(--mono); font-weight: 600; }

button { font: inherit; color: inherit; background: none; border: none; cursor: pointer; }
:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; border-radius: 3px; }

.btn {
  background: var(--panel3);
  border: 1px solid var(--border2);
  border-radius: 6px;
  padding: 3px 10px;
  min-height: 26px;
  font-size: 11.5px;
  color: var(--text);
  transition: background .12s, border-color .12s;
}
.btn:hover:not(:disabled) { background: #232c42; border-color: #3a4560; }
.btn:disabled { color: #97a1b3; background: #141a27; border-color: #222a3c; cursor: default; }
.btn-sm { padding: 2px 8px; font-size: 11px; min-height: 24px; }

/* custom checkbox — 24×24 target */
input[type="checkbox"] {
  appearance: none; -webkit-appearance: none;
  width: 24px; height: 24px; flex: none;
  border: 1px solid var(--border2); border-radius: 6px;
  background: var(--panel2); cursor: pointer; position: relative;
}
input[type="checkbox"]:checked { background: var(--c-c); border-color: var(--c-c); }
input[type="checkbox"]:checked::after {
  content: "✓"; position: absolute; inset: 0;
  display: grid; place-items: center;
  color: #0b2536; font-size: 14px; font-weight: 700;
}

/* ---------- top bar ---------- */
