    var sd = DIM[state.channels.size];
    var sz = el('span', 'lg-item');
    var d1 = el('i', 'lg-dot'); d1.style.width = '4px'; d1.style.height = '4px';
    var d2 = el('i', 'lg-dot'); d2.style.width = '11px'; d2.style.height = '11px';
