  function buildFilterEditor() {
    var d = DIM[editingDim];
    filterEditor.textContent = '';
    {
      var row = el('div', 'f-row'); row.id = 'f-row-' + d.id;
      var head = el('div', 'f-head');
      head.appendChild(el('span', null, d.label));
