    });
  }

  function toggleSetVal(d, val, exclude, actor) {
    act('filter', actor, (exclude ? '排除 ' : '恢复 ') + d.label + '：' + val, function (s) {
      var f = s.filters[d.id] || { off: [] };
      f.off = f.off || [];
