      if (exclude && i < 0) f.off.push(val);
      if (!exclude && i >= 0) f.off.splice(i, 1);
      if (!f.off.length) delete s.filters[d.id]; else s.filters[d.id] = f;
    });
  }

  function afterLiveFilter(d) {
