  }
  function updateFilterControls() {
    D.dimensions.forEach(function (d) { var r = fRefs[d.id]; if (r) updateFilterRow(d, r); });
  }

  function renderChips() {
    var box = $('filter-chips'); box.textContent = '';
    var n = 0;
    D.dimensions.forEach(function (d) {
