  }
  function filterLabel(id) {
    var f = state.filters[id], d = DIM[id];
    if (f.lo != null) return d.label + ' ' + fmtN(f.lo) + ' – ' + fmtN(f.hi) + (d.unit ? ' ' + d.unit : '');
