    var d2 = el('i', 'lg-dot'); d2.style.width = '11px'; d2.style.height = '11px';
    sz.appendChild(d1); sz.appendChild(d2);
    sz.appendChild(el('span', null, sd.label + (sd.unit ? ' ' + sd.unit : '') + ' ' + fmtN(sd.dom[0]) + '–' + fmtN(sd.dom[1])));
